import { describe, expect, test } from "bun:test";
import {
  parseHeliumData,
  transformBangs,
  validateBangs,
} from "../scripts/sync-helium-bangs";

const SAMPLE = `// Generated at 2026-11-10T08:56:42.761Z
// DO NOT edit this file manually!
// MIT License
// Copyright (c) 2024 Kagi Search, 2026 imput

[
 {
  "s": "Google",
  "ts": [ "g", "goog", "google" ],
  "u": "https://www.google.com/search?q={searchTerms}",
 },
 {
  "s": "Hacker News",
  "ts": [ "hn" ],
  "f": 14,
  "u": "https://hn.algolia.com/?q={searchTerms}",
 }
]
`;

describe("Helium sync transforms", () => {
  test("parses comments and trailing commas", () => {
    const parsed = parseHeliumData(SAMPLE);
    expect(parsed.generatedAt).toBe("2026-11-10T08:56:42.761Z");
    expect(parsed.bangs).toHaveLength(2);
    expect(parsed.sha256).toHaveLength(64);
  });

  test("expands aliases, derives domains, and defaults format flags", () => {
    const records = transformBangs(parseHeliumData(SAMPLE).bangs);
    expect(records.map((record) => record.trigger)).toEqual([
      "g",
      "goog",
      "google",
      "hn",
    ]);
    expect(records[0].canonical).toBe("g");
    expect(records[0].domain).toBe("www.google.com");
    expect(records[0].formatMask).toBe(15);
    expect(records[3].formatMask).toBe(14);
  });

  test("rejects duplicate or malformed triggers", () => {
    expect(() =>
      validateBangs([
        {
          s: "One",
          ts: ["same"],
          u: "https://one.example/?q={searchTerms}",
        },
        {
          s: "Two",
          ts: ["same"],
          u: "https://two.example/?q={searchTerms}",
        },
      ]),
    ).toThrow("Duplicate Helium trigger");
  });
});
